const input = $json.body ?? $json;
const clean = (value, max = 500) => String(value ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const name = clean(input.name, 120);
const company = clean(input.company, 160);
const email = clean(input.email, 254).toLowerCase();
const phone = clean(input.phone, 40);
const website = clean(input.website, 300);
const interest = clean(input.interest ?? input.anliegen, 200);
const message = clean(input.message ?? input.nachricht, 3000);
const privacy = input.privacy === true || input.privacy === 'true' || input.privacy === 'on';
const honeypot = clean(input.websiteConfirm, 200);
const startedAt = Number(input.formStartedAt || 0);
const submittedAt = clean(input.submittedAt, 60);
const receivedAt = new Date().toISOString();
const missingFields = [];
if (!name) missingFields.push('Name');
if (!email) missingFields.push('E-Mail');
if (!interest) missingFields.push('Anliegen');
if (!privacy) missingFields.push('DSGVO-Zustimmung');
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
let errorCode = '';
if (honeypot) errorCode = 'spam_detected';
else if (missingFields.length) errorCode = 'missing_required_fields';
else if (!emailValid) errorCode = 'invalid_email';
else if (startedAt && Date.now() - startedAt < 1500) errorCode = 'submitted_too_fast';
let leadScore = 0;
if (website) leadScore += 10;
if (company) leadScore += 10;
if (interest.length >= 8) leadScore += 20;
if (/automat|prozess/i.test(interest + ' ' + message)) leadScore += 25;
if (/landingpage|website|webseite/i.test(interest + ' ' + message)) leadScore += 20;
if (phone) leadScore += 10;
if (message.length >= 40) leadScore += 5;
leadScore = Math.min(100, leadScore);
const priority = leadScore >= 80 ? 'A-Lead' : leadScore >= 50 ? 'B-Lead' : 'C-Lead';
const hash = [...email].reduce((value, char) => ((value << 5) - value + char.charCodeAt(0)) | 0, 0);
const datePart = receivedAt.slice(0, 10).replace(/-/g, '');
const leadId = `NW-${datePart}-${Math.abs(hash).toString(36).toUpperCase()}-${Date.now().toString(36).toUpperCase()}`;
const followUpDate = new Date(Date.now() + 3 * 86400000).toISOString().slice(0, 10);
const nextStep = priority === 'A-Lead' ? 'Innerhalb eines Werktags persönlich kontaktieren' : priority === 'B-Lead' ? 'Bedarf prüfen und Erstgespräch anbieten' : 'Anfrage sichten und Rückmeldung vorbereiten';
const offerPotential = /automat/i.test(interest + ' ' + message) ? 'Automation & Betreuung' : /website|webseite|landingpage/i.test(interest + ' ' + message) ? 'Handwerker Landingpage' : 'Lead-System / Beratung';
return [{ json: { valid: !errorCode, errorCode, missingFields, leadId, createdAt: submittedAt || receivedAt, receivedAt, name, company, email, phone, website, industry: clean(input.industry ?? input.branche, 120), interest, message, privacy, source: 'Website', pageUrl: clean(input.pageUrl, 500), leadScore, priority, status: 'Neu', offerPotential, nextStep, followUpDate } }];

const lead = $('Lead validieren & bewerten').item.json;
const response = $json ?? {};
const apiFailed = Boolean(response.error || response.statusCode >= 400 || (!Array.isArray(response.results) && response.object === 'error'));
if (apiFailed) return [{ json: { ...lead, storageReady: false, storageError: response.message || 'Notion-Duplikatprüfung fehlgeschlagen' } }];
const matches = Array.isArray(response.results) ? response.results : [];
const duplicate = matches.length > 0;
const duplicatePageId = duplicate ? matches[0].id : '';
const rich = (text, max = 1900) => [{ type: 'text', text: { content: String(text || '').slice(0, max) } }];
const properties = {
  'Firma / Name': { title: rich(lead.company || lead.name) },
  'Lead ID': { rich_text: rich(lead.leadId) },
  'Erstellungsdatum': { date: { start: lead.createdAt } },
  'Ansprechpartner': { rich_text: rich(lead.name) },
  'E-Mail': { email: lead.email },
  'Telefon': { phone_number: lead.phone || null },
  'Website': { url: lead.website || null },
  'Branche': { rich_text: rich(lead.industry) },
  'Anliegen': { rich_text: rich(lead.interest) },
  'Nachricht': { rich_text: rich(lead.message) },
  'Lead-Quelle': { select: { name: 'Website' } },
  'Status': { select: { name: 'Neu' } },
  'Priorität': { select: { name: lead.priority } },
  'Lead Score': { number: lead.leadScore },
  'Angebotspotenzial': { rich_text: rich(lead.offerPotential) },
  'Nächster Schritt': { rich_text: rich(lead.nextStep) },
  'Follow-up Datum': { date: { start: lead.followUpDate } },
  'Notizen': { rich_text: rich(duplicate ? `Erneute Anfrage am ${lead.receivedAt}. Vorhandener Datensatz aktualisiert.` : `Erstellt durch Lead Intake am ${lead.receivedAt}.`) },
  'Angebot erstellt': { checkbox: false },
  'Angebot versendet': { checkbox: false },
  'Kunde': { checkbox: false }
};
return [{ json: { ...lead, storageReady: true, duplicate, duplicatePageId, notionCreateBody: { parent: { database_id: 'NOVAWERK_NOTION_DATABASE_ID' }, properties }, notionUpdateBody: { properties } } }];

const lead = $('Duplikat + CRM-Payload').item.json;
const response = $json ?? {};
const stored = Boolean(response.id) && !response.error;
return [{ json: { ...lead, stored, notionPageId: response.id || lead.duplicatePageId || '', storageError: stored ? '' : (response.message || 'CRM-Speicherung fehlgeschlagen') } }];
